package vn.svframe.loadprobe;
import java.nio.file.*;import java.lang.management.*;import java.util.*;import net.fabricmc.api.ModInitializer;import net.fabricmc.fabric.api.command.v2.CommandRegistrationCallback;import net.fabricmc.loader.api.FabricLoader;import net.minecraft.text.Text;import static net.minecraft.server.command.CommandManager.*;
public final class LoadProbe implements ModInitializer {
 static boolean recording,measuring;static final long[] times=new long[12000],allocations=new long[12000];static int count,overflow;static long start,allocated,wall,cpuStart;static Object gcStart;
 static final com.sun.management.ThreadMXBean THREADS=(com.sun.management.ThreadMXBean)ManagementFactory.getThreadMXBean();
 static final com.sun.management.OperatingSystemMXBean OS=(com.sun.management.OperatingSystemMXBean)ManagementFactory.getOperatingSystemMXBean();
 public static void begin(){measuring=recording;if(measuring){start=System.nanoTime();allocated=THREADS.getThreadAllocatedBytes(Thread.currentThread().threadId());}}
 public static void end(){if(recording&&measuring){long elapsed=System.nanoTime()-start,bytes=THREADS.getThreadAllocatedBytes(Thread.currentThread().threadId())-allocated;if(count<times.length){times[count]=elapsed;allocations[count++]=bytes;}else overflow++;}}
 static Object gc(){var rows=new ArrayList<Map<String,Object>>();for(var bean:ManagementFactory.getGarbageCollectorMXBeans())rows.add(Map.of("name",bean.getName(),"count",bean.getCollectionCount(),"timeMs",bean.getCollectionTime()));return rows;}
 @Override public void onInitialize(){if(!"1".equals(System.getenv("SVFRAME_RUNTIME_QA")))throw new IllegalStateException("QA probe requires SVFRAME_RUNTIME_QA=1; remove it from production");CommandRegistrationCallback.EVENT.register((dispatcher,access,environment)->dispatcher.register(literal("loadcatalogqa").requires(src->src.hasPermissionLevel(4)).then(argument("player",net.minecraft.command.argument.EntityArgumentType.player()).executes(c->{
 try{
  var player=net.minecraft.command.argument.EntityArgumentType.getPlayer(c,"player");var type=Class.forName("vn.svframe.svframelib.skill.PlayerAbilityShop");var provider=type.getMethod("get").invoke(null);var rows=(java.util.List<?>)type.getMethod("catalog",net.minecraft.server.network.ServerPlayerEntity.class).invoke(provider,player);
  boolean sliced=false;try{var method=provider.getClass().getMethod("catalogPage",net.minecraft.server.network.ServerPlayerEntity.class,int.class,int.class);var all=new java.util.ArrayList<>();int cursor=0,total=0;do{var page=(java.util.Map<?,?>)method.invoke(provider,player,cursor,8);var batch=(java.util.List<?>)page.get("rows");if(batch.size()>8)throw new IllegalStateException("Unbounded page");all.addAll(batch);cursor=((Number)page.get("next")).intValue();total=((Number)page.get("total")).intValue();}while(cursor<total);if(!all.equals(rows))throw new IllegalStateException("Sliced catalog differs from native full catalog");sliced=true;}catch(NoSuchMethodException baseline){}
  Path path=FabricLoader.getInstance().getConfigDir().resolve("FantasyHubLoadProbe/catalog.json");Files.createDirectories(path.getParent());Files.writeString(path,new com.google.gson.Gson().toJson(java.util.Map.of("rows",rows,"sliceEqualityChecked",sliced)));c.getSource().sendFeedback(()->Text.literal("Catalog QA: "+rows.size()+" rows exported"),false);return rows.size();
 }catch(Exception failure){throw new IllegalStateException(failure);}
}))));
CommandRegistrationCallback.EVENT.register((d,a,e)->d.register(literal("loadprobe").requires(s->s.hasPermissionLevel(4)).then(literal("start").executes(c->{count=overflow=0;FantasyProbe.reset();wall=System.currentTimeMillis();cpuStart=OS.getProcessCpuTime();gcStart=gc();recording=true;return 1;})).then(literal("stop").then(argument("label",com.mojang.brigadier.arguments.StringArgumentType.word()).executes(c->{recording=false;String label=com.mojang.brigadier.arguments.StringArgumentType.getString(c,"label");if(!label.matches("[A-Za-z0-9_-]{1,64}"))return 0;var data=new LinkedHashMap<String,Object>();data.put("fantasySync",FantasyProbe.snapshot());data.put("startEpochMs",wall);data.put("endEpochMs",System.currentTimeMillis());data.put("tickNanos",Arrays.copyOf(times,count));data.put("mainAllocatedBytes",Arrays.copyOf(allocations,count));data.put("overflow",overflow);data.put("processCpuNanos",OS.getProcessCpuTime()-cpuStart);data.put("gcStart",gcStart);data.put("gcEnd",gc());data.put("heapUsed",ManagementFactory.getMemoryMXBean().getHeapMemoryUsage().getUsed());data.put("players",c.getSource().getServer().getCurrentPlayerCount());try{Path path=FabricLoader.getInstance().getConfigDir().resolve("FantasyHubLoadProbe/"+label+".json");Files.createDirectories(path.getParent());Files.writeString(path,new com.google.gson.Gson().toJson(data));c.getSource().sendFeedback(()->Text.literal("QA probe: "+count+" ticks saved to "+path.getFileName()),false);return 1;}catch(Exception failed){throw new RuntimeException(failed);}})))));}
}
